import type { AiModel } from '@shared/types'
import { AiError, request, type CallContext } from './http'
import { isImageModel } from './wire'
import type {
  ImageAdapter,
  ImageRequest,
  ImageResult
} from './image-wire'

/**
 * Image generation, Google's dialect.
 *
 * Ships first of the two because it fits the existing JSON `request()`
 * unchanged: references go in as `inline_data` parts on an ordinary
 * `:generateContent` body, and the generated bytes come back base64 in the
 * response's `inlineData` parts. Nothing about it needs multipart, which is the
 * thing standing between `openai-image.ts` and reference support.
 *
 * Like every other adapter here it opens no socket of its own — a refused image
 * key gets the same sentence as a refused prompt key rather than a second,
 * worse copy of the same logic.
 */

const authHeaders = (ctx: CallContext): Record<string, string> => ({
  'x-goog-api-key': ctx.apiKey
})

/**
 * How long one image is worth waiting for.
 *
 * A property of the protocol rather than of the job, which is why it is here
 * and not in `ImageRequest`: unlike a token budget, no caller has a useful
 * opinion about it. Two minutes is well past what these models take and well
 * short of the point where waiting is helping.
 */
const IMAGE_TIMEOUT_MS = 120_000

function assertGoogle(ctx: CallContext): void {
  if (ctx.provider !== 'gemini') {
    throw new AiError(
      `This is Google's image dialect, but the image slot is set to ${ctx.label}. Set the image slot to Google Gemini in Settings, or give it a key from a provider whose image API Day Deck speaks.`,
      'config'
    )
  }
}

/**
 * The models the image slot may actually be pointed at here.
 *
 * Filtered on the generation method this file uses, not on the name. Imagen is
 * excluded by that alone — it answers `:predict`, not `:generateContent`, so
 * offering it would be offering a button that cannot work.
 */
async function listModels(ctx: CallContext): Promise<AiModel[]> {
  assertGoogle(ctx)

  const data = (await request(ctx, '/models?pageSize=200', {
    headers: authHeaders(ctx),
    timeoutMs: 20_000
  })) as {
    models?: Array<{
      name: string
      displayName?: string
      supportedGenerationMethods?: string[]
    }>
  }

  return (data.models ?? [])
    .map((m) => ({
      id: m.name.replace(/^models\//, ''),
      displayName: m.displayName ?? m.name.replace(/^models\//, ''),
      methods: m.supportedGenerationMethods ?? []
    }))
    .filter((m) => isImageModel(m.id) && m.methods.includes('generateContent'))
    .map(({ id, displayName }) => ({
      id,
      displayName,
      inputTokenLimit: null
    }))
    .sort((a, b) => a.id.localeCompare(b.id))
}

/** Both spellings, because the response has been seen to use either. */
interface InlinePart {
  inlineData?: { mimeType?: string; mime_type?: string; data?: string }
  inline_data?: { mimeType?: string; mime_type?: string; data?: string }
  text?: string
}

function readImages(payload: unknown, ctx: CallContext): ImageResult[] {
  const data = payload as {
    candidates?: Array<{
      content?: { parts?: InlinePart[] }
      finishReason?: string
    }>
    promptFeedback?: { blockReason?: string }
  }

  const blocked = data.promptFeedback?.blockReason
  if (blocked) {
    throw new AiError(
      `${ctx.label} declined to generate this image (${blocked}). Rewrite the description and try again.`,
      'unknown'
    )
  }

  const out: ImageResult[] = []
  for (const candidate of data.candidates ?? []) {
    for (const part of candidate.content?.parts ?? []) {
      const inline = part.inlineData ?? part.inline_data
      if (!inline?.data) continue
      out.push({
        bytes: Buffer.from(inline.data, 'base64'),
        mimeType: inline.mimeType ?? inline.mime_type ?? 'image/png'
      })
    }
  }

  if (out.length === 0) {
    // A model that answered in words instead of pixels is the common shape of
    // this failure, and quoting it is the difference between a fixable prompt
    // and "no image came back".
    const said = (data.candidates?.[0]?.content?.parts ?? [])
      .map((p) => p.text ?? '')
      .join(' ')
      .trim()
    throw new AiError(
      said
        ? `${ctx.label} replied with text instead of an image: ${said.slice(0, 300)}`
        : `${ctx.label} returned no image for this request.`,
      'parse'
    )
  }
  return out
}

/**
 * A surface that predates a field says so by name — the same retreat rule
 * `gemini.ts` follows, and for the same reason.
 *
 * Two fields are worth retreating on here. `imageConfig` is new and older image
 * surfaces reject it outright. `responseModalities: ['IMAGE']` is accepted by
 * the current image models and refused by the preview one, which requires TEXT
 * alongside — so the retreat is to ask for both rather than to drop the field,
 * because dropping it gets a text answer to an image request.
 */
const REJECTED_IMAGE_CONFIG = /image[_-]?config|aspect[_ -]?ratio/i
const REJECTED_MODALITIES = /modalit/i

async function generate(
  ctx: CallContext,
  req: ImageRequest
): Promise<ImageResult[]> {
  assertGoogle(ctx)

  const path = `/models/${encodeURIComponent(req.model)}:generateContent`

  let imageConfig = true
  let imageOnly = true

  for (;;) {
    const parts = [
      ...req.references.map((ref) => ({
        inline_data: {
          mime_type: ref.mimeType,
          data: ref.bytes.toString('base64')
        }
      })),
      { text: req.prompt }
    ]

    const body = {
      contents: [{ role: 'user', parts }],
      generationConfig: {
        responseModalities: imageOnly ? ['IMAGE'] : ['TEXT', 'IMAGE'],
        ...(imageConfig
          ? { imageConfig: { aspectRatio: req.aspectRatio } }
          : {})
      }
    }

    try {
      return readImages(
        await request(ctx, path, {
          method: 'POST',
          headers: authHeaders(ctx),
          timeoutMs: IMAGE_TIMEOUT_MS,
          body
        }),
        ctx
      )
    } catch (err) {
      // `kind` as well as status: Google answers a bad key with a 400 too, and
      // no field this loop can drop will make a rejected key work.
      if (
        !(err instanceof AiError) ||
        err.status !== 400 ||
        err.kind === 'auth'
      ) {
        throw err
      }

      if (imageConfig && REJECTED_IMAGE_CONFIG.test(err.message)) {
        imageConfig = false
        continue
      }
      if (imageOnly && REJECTED_MODALITIES.test(err.message)) {
        imageOnly = false
        continue
      }
      throw err
    }
  }
}

export const geminiImage: ImageAdapter = {
  // One image per request. Stated rather than assumed: `candidateCount` is a
  // field on this endpoint, and the image models ignore it — asking for three
  // and being billed for one that arrives alone is exactly the shape of
  // surprise `maxSamples` exists to prevent.
  maxImages: 1,
  // Three is what the current image models take without degrading. The pack
  // only ever sends one — the approved portrait — so this ceiling never bites
  // today; it is stated because the caller has to read the number off the
  // adapter rather than assume it.
  maxReferences: 3,
  listModels,
  generate
}
